"""Optimal quota-constrained follow-up plan.

An assignment is one unit of flow from the source, down the request quota
forest (consuming a unit at the request's group and every ancestor),
across exactly one request/offer pair edge, and up the offer quota forest
(consuming a unit at the offer's group and every ancestor) into the sink.
Each subtree constraint is a plain aggregate over the requests or offers
inside that subtree, so routing the request side from the root downwards
and the offer side from the offers upwards makes every integral flow of
this network correspond to a feasible assignment and vice versa.

Cost lives only on the pair edges, so a min-cost maximum flow yields a
maximum-cardinality plan of minimum total offer cost.
"""
import heapq

from protocols import probe_script

SOURCE = 0
SINK = 1
INFINITY = float('inf')


def _children(quotas):
    result={}
    for name,row in quotas.items():
        parent=row['parent']
        if parent is not None:
            result.setdefault(parent,[]).append(name)
    return result


def _order(quotas,children):
    """Breadth-first order over one quota forest (parents before children)."""
    queue=[name for name,row in quotas.items() if row['parent'] is None]
    at=0
    while at<len(queue):
        for child in children.get(queue[at],()):
            queue.append(child)
        at+=1
    return queue


def _subtree_load(quotas,order,direct):
    """Aggregate demand over every subtree of one quota forest."""
    load=dict(direct)
    for name in reversed(order):
        parent=quotas[name]['parent']
        if parent is not None:
            load[parent]=load.get(parent,0)+load.get(name,0)
    return load


def _wire(quotas,order,load,allocate,placeholder,downward,edges):
    """Add one quota forest to the flow network.

    Returns a map from every quota node to the network node its traffic
    passes through. Nodes whose capacity can never bind are contracted
    into their nearest binding ancestor, or into `placeholder`.
    """
    attach={}
    for name in order:
        parent=quotas[name]['parent']
        outer=placeholder if parent is None else attach[parent]
        if quotas[name]['capacity']<load.get(name,0):
            attach[name]=outer
            continue
        node=allocate()
        attach[name]=node
        if downward:
            edges.append((outer,node,quotas[name]['capacity'],0))
        else:
            edges.append((node,outer,quotas[name]['capacity'],0))
    return attach


def min_cost_flow(count,edges,source,sink):
    """Successive shortest paths with potentials and blocking flows.

    Returns `(value, flow)` where `flow[i]` is the flow carried by the
    i-th edge of `edges`.
    """
    to=[]
    cap=[]
    cost=[]
    adj=[[] for _ in range(count)]
    for tail,head,room,weight in edges:
        adj[tail].append(len(cap)); to.append(head); cap.append(room); cost.append(weight)
        adj[head].append(len(cap)); to.append(tail); cap.append(0); cost.append(-weight)
    potential=[0]*count
    value=0
    parent=[-1]*count
    while True:
        distance=[INFINITY]*count
        distance[source]=0
        seen=bytearray(count)
        heap=[(0,source)]
        push=heapq.heappush
        pop=heapq.heappop
        while heap:
            step,u=pop(heap)
            if seen[u]:
                continue
            seen[u]=1
            pu=potential[u]
            for edge in adj[u]:
                if cap[edge]>0:
                    head=to[edge]
                    if not seen[head]:
                        reach=step+cost[edge]+pu-potential[head]
                        if reach<distance[head]:
                            distance[head]=reach
                            parent[head]=edge
                            push(heap,(reach,head))
        if distance[sink]==INFINITY:
            break
        for node in range(count):
            if distance[node]<INFINITY:
                potential[node]+=distance[node]
        level=[-1]*count
        level[source]=0
        queue=[source]
        pushed=0
        while queue:
            nxt=[]
            for u in queue:
                pu=potential[u]
                lu=level[u]
                for edge in adj[u]:
                    if cap[edge]>0:
                        head=to[edge]
                        if level[head]<0 and cost[edge]+pu-potential[head]==0:
                            level[head]=lu+1
                            nxt.append(head)
            queue=nxt
        ptr=[0]*count
        while True:
            path=[]
            u=source
            found=False
            while True:
                if u==sink:
                    found=True
                    break
                moved=False
                au=adj[u]
                lu=level[u]
                pu=potential[u]
                while ptr[u]<len(au):
                    edge=au[ptr[u]]
                    if cap[edge]>0:
                        head=to[edge]
                        if level[head]==lu+1 and cost[edge]+pu-potential[head]==0:
                            path.append(edge)
                            u=head
                            moved=True
                            break
                    ptr[u]+=1
                if moved:
                    continue
                if u==source:
                    break
                level[u]=-1
                edge=path.pop()
                u=to[edge^1]
                ptr[u]+=1
            if not found:
                break
            room=min(cap[edge] for edge in path)
            for edge in path:
                cap[edge]-=room
                cap[edge^1]+=room
            pushed+=room
            value+=room
            cut=0
            while cut<len(path) and cap[path[cut]]>0:
                cut+=1
            del path[cut:]
            u=source if cut==0 else to[path[cut-1]]
        if pushed==0:
            # Defensive fallback: augment along one exact shortest path.
            path=[]
            node=sink
            while node!=source:
                edge=parent[node]
                if edge<0:
                    break
                path.append(edge)
                node=to[edge^1]
            if path and node==source:
                room=min(cap[edge] for edge in path)
                for edge in path:
                    cap[edge]-=room
                    cap[edge^1]+=room
                value+=room
    return value,[edges[index][2]-cap[index*2] for index in range(len(edges))]


def solve(context,active):
    """Return the optimal `{resolved,cost,assignments}` plan."""
    requests=context['requests']
    offers=context['offers']
    leases=context['leases']
    allowed={}
    for request_id in requests:
        if active[request_id]:
            allowed[request_id]=[]
    for offer_id,offer in offers.items():
        if offer['capacity']<=0:
            continue
        low=offer['lo']
        high=offer['hi']
        when=offer['time']
        service=offer['service']
        for request_id in offer['requests']:
            pending=allowed.get(request_id)
            if pending is None:
                continue
            row=requests[request_id]
            if service!=row['service']:
                continue
            if not (row['at']<=when<leases[row['lease']]['end']):
                continue
            if low<=row['address']<=high:
                pending.append(offer_id)
    classes=[]
    index={}
    for request_id in sorted(allowed):
        pending=allowed[request_id]
        if not pending:
            continue
        row=requests[request_id]
        key=(row['group'],tuple(pending))
        position=index.get(key)
        if position is None:
            position=len(classes)
            index[key]=position
            classes.append([row['group'],tuple(pending),0,[]])
        classes[position][2]+=1
        classes[position][3].append(request_id)
    offer_classes={}
    for position,entry in enumerate(classes):
        for offer_id in entry[1]:
            offer_classes.setdefault(offer_id,[]).append(position)
    merged=[]
    merged_index={}
    for offer_id,offer in offers.items():
        members=offer_classes.get(offer_id)
        if not members:
            continue
        key=(offer['group'],offer['cost'],tuple(members))
        position=merged_index.get(key)
        if position is None:
            position=len(merged)
            merged_index[key]=position
            merged.append([offer['group'],offer['cost'],0,[],members])
        merged[position][2]+=offer['capacity']
        merged[position][3].append(offer_id)
    keep_class=[True]*len(classes)
    keep_offer=[True]*len(merged)
    class_offers=[]
    while True:
        class_offers=[[] for _ in classes]
        for position in range(len(merged)):
            if not keep_offer[position]:
                continue
            for member in merged[position][4]:
                if keep_class[member]:
                    class_offers[member].append(position)
        changed=False
        for position in range(len(classes)):
            if keep_class[position] and not class_offers[position]:
                keep_class[position]=False
                changed=True
        for position in range(len(merged)):
            if keep_offer[position] and not any(keep_class[member]
                                                for member in merged[position][4]):
                keep_offer[position]=False
                changed=True
        if not changed:
            break
    live_classes=[position for position in range(len(classes)) if keep_class[position]]
    live_offers=[position for position in range(len(merged)) if keep_offer[position]]
    if not live_classes or not live_offers:
        return {'resolved':0,'cost':0,'assignments':[]}
    budget=len(classes)+len(merged)+len(context['request_quotas'])+len(context['offer_quotas'])
    counter=[2]

    def allocate():
        node=counter[0]
        counter[0]+=1
        return node

    edges=[]
    children=_children(context['request_quotas'])
    order=_order(context['request_quotas'],children)
    direct={}
    for position in live_classes:
        group=classes[position][0]
        direct[group]=direct.get(group,0)+classes[position][2]
    load=_subtree_load(context['request_quotas'],order,direct)
    request_attach=_wire(context['request_quotas'],order,load,allocate,SOURCE,True,edges)
    for position in live_classes:
        node=allocate()
        classes[position].append(node)
        edges.append((request_attach[classes[position][0]],node,classes[position][2],0))
    offer_children=_children(context['offer_quotas'])
    offer_order=_order(context['offer_quotas'],offer_children)
    offer_direct={}
    for position in live_offers:
        group=merged[position][0]
        offer_direct[group]=offer_direct.get(group,0)+merged[position][2]
    offer_load=_subtree_load(context['offer_quotas'],offer_order,offer_direct)
    offer_attach=_wire(context['offer_quotas'],offer_order,offer_load,allocate,SINK,False,edges)
    pair_edge={}
    for position in live_offers:
        node=allocate()
        merged[position].append(node)
        edges.append((node,offer_attach[merged[position][0]],merged[position][2],
                      merged[position][1]))
    for class_position in live_classes:
        node=classes[class_position][4]
        room=classes[class_position][2]
        for offer_position in class_offers[class_position]:
            pair_edge[(class_position,offer_position)]=len(edges)
            edges.append((node,merged[offer_position][4],room,0))
    min_cost_flow(counter[0],edges,SOURCE,SINK)
    flow=[edges[position][2]-cap[position*2] for position in range(len(edges))]
    chosen=[]
    for class_position in live_classes:
        members=classes[class_position][3]
        at=0
        for offer_position in class_offers[class_position]:
            taken=flow[pair_edge[(class_position,offer_position)]]
            if taken<=0:
                continue
            for request_id in members[at:at+taken]:
                chosen.append((request_id,offer_position))
            at+=taken
    per_offer={}
    for request_id,offer_position in chosen:
        bucket=per_offer.get(offer_position)
        if bucket is None:
            per_offer[offer_position]=[request_id]
        else:
            bucket.append(request_id)
    scripts={}
    assignments=[]
    for offer_position in sorted(per_offer):
        pending=per_offer[offer_position]
        remaining=len(pending)
        at=0
        for offer_id in merged[offer_position][3]:
            if remaining<=0:
                break
            capacity=offers[offer_id]['capacity']
            if capacity<=0:
                continue
            take=capacity if capacity<remaining else remaining
            kind=offers[offer_id]['service']
            packets=scripts.get(kind)
            if packets is None:
                packets=scripts[kind]=probe_script(kind)
            send,finish=packets
            for request_id in pending[at:at+take]:
                assignments.append({'request':request_id,'offer':offer_id,
                                    'send':send,'finish':finish})
            at+=take
            remaining-=take
    assignments.sort(key=lambda item:item['request'])
    total=0
    for item in assignments:
        total+=context['offers'][item['offer']]['cost']
    return {'resolved':len(assignments),'cost':total,'assignments':assignments}
PYEOF
